const ubState={balances:{},totals:{usd:0,byToken:{},byNetwork:{}},loaded:false,loading:false,error:null,history:[],invoices:[],rules:[],analytics:{totalSent:0,totalReceived:0,txCount:0,byToken:{},byDay:{}},agents:{},agentLog:[],ledger:[],contacts:[],profile:{riskScore:0,activityLevel:'low',preferredNetwork:'arc',totalValue:0,onChainAge:0}};

const ub$=id=>document.getElementById(id);
const ubText=(id,t)=>{const e=ub$(id);if(e)e.textContent=t;};
const ubHTML=(id,h)=>{const e=ub$(id);if(e)e.innerHTML=h;};
const ubShow=id=>{const e=ub$(id);if(e)e.classList.remove('hidden');};
const ubHide=id=>{const e=ub$(id);if(e)e.classList.add('hidden');};
function ubSetVal(id,v){const e=ub$(id);if(e)e.value=v;}
async function ubEthCall(rpc,to,data){var k=rpc+to+data.slice(0,74);var c=ubState._rpcCache;if(c&&c[k]&&(Date.now()-c[k].ts)<30000)return c[k].val;const r=await fetch(rpc,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'eth_call',params:[{to,data},'latest']})});const j=await r.json();if(j.error)throw new Error(j.error.message);var v=j.result;if(!ubState._rpcCache)ubState._rpcCache={};ubState._rpcCache[k]={val:v,ts:Date.now()};return v;}
async function ubFetchTokenBalance(nk,sym,w){const n=UB_NETWORKS[nk],a=n[sym.toLowerCase()];if(!a)return 0n;try{const h=await ubEthCall(n.rpc,a,'0x70a08231'+w.replace('0x','').toLowerCase().padStart(64,'0'));return h&&h!=='0x'?BigInt(h):0n;}catch(_){return 0n;}}
function ubFormatUSD(v){if(v>=1e6)return'$'+(v/1e6).toFixed(2)+'M';if(v>=1e3)return'$'+(v/1e3).toFixed(2)+'K';return'$'+v.toFixed(2);}
function ubFmtNum(v){return v.toLocaleString(void 0,{minimumFractionDigits:2,maximumFractionDigits:4});}
function ubTimeAgo(ts){if(!ts)return'';var d=(Date.now()-new Date(ts).getTime())/1000;if(d<60)return'now';if(d<3600)return Math.floor(d/60)+'m ago';if(d<86400)return Math.floor(d/3600)+'h ago';return Math.floor(d/86400)+'d ago';}

// ═══════════════════ UNIFIED LEDGER ═══════════════════
function ubFetchUnifiedLedger(){var events=[];try{var bh=JSON.parse(localStorage.getItem('bridge_history_v1')||'[]');for(var h of bh.slice(0,20))events.push({type:'bridge',icon:'fa-right-left',color:'text-cyan-400',bg:'bg-cyan-900/20 border-cyan-700/30',label:'Bridge',amount:h.amount||'',token:h.token||'USDC',detail:(h.fromNetwork||h.fromChain||'')+' → '+(h.toNetwork||h.toChain||''),txHash:h.txHash||'',time:h.timestamp||'',status:'completed',source:'bridge'});}catch(_){}try{var ph=JSON.parse(localStorage.getItem('arc_pay_history')||'[]');for(var p of ph.slice(0,20))events.push({type:'payment',icon:'fa-paper-plane',color:'text-purple-400',bg:'bg-purple-900/20 border-purple-700/30',label:'Payment',amount:p.amount||'',token:p.token||'USDC',detail:'To: '+((p.to||p.recipient||'').slice(0,10)+'...'),txHash:p.txHash||'',time:p.timestamp||p.date||'',status:p.status||'completed',source:'payments'});}catch(_){} ubLoadInvoices();for(var inv of ubState.invoices.slice(0,20))events.push({type:inv.status==='paid'?'payment':'invoice',icon:inv.status==='paid'?'fa-check':'fa-file-invoice',color:inv.status==='paid'?'text-green-400':'text-yellow-400',bg:inv.status==='paid'?'bg-green-900/20 border-green-700/30':'bg-yellow-900/20 border-yellow-700/30',label:inv.status==='paid'?'Settled':inv.status.charAt(0).toUpperCase()+inv.status.slice(1),amount:inv.amount+'',token:inv.token,detail:inv.note||'',txHash:inv.paidTx||'',time:inv.settledAt||inv.created||'',status:inv.status,source:'invoice'}); try{var al=JSON.parse(localStorage.getItem('ub_agent_log_v1')||'[]');for(var a of al.slice(0,20)){var ag=AGENT_REGISTRY[a.agentId];events.push({type:'agent',icon:ag?ag.icon:'fa-robot',color:ag?ag.color:'text-violet-400',bg:'bg-violet-900/20 border-violet-700/30',label:ag?ag.name:'Agent',amount:a.summary||'',token:'',detail:a.action||'',txHash:'',time:a.timestamp||'',status:a.action==='completed'?'completed':a.action==='failed'?'failed':'pending',source:'agent'});}}catch(_){} events.sort((a,b)=>(b.time||'').localeCompare(a.time||''));ubState.ledger=events;ubRenderLedger();}

function ubRenderLedger(){var el=ub$('ub-ledger-list');if(!el)return;if(!ubState.ledger.length){el.innerHTML='<div class="text-center py-8 text-gray-600 text-sm"><i class="fas fa-book text-2xl mb-2 block"></i>Ledger empty</div>';return;}el.innerHTML=ubState.ledger.slice(0,30).map(e=>'<div class="flex items-center gap-3 px-4 py-2.5 border-b border-gray-700/30 hover:bg-gray-800/20"><div class="w-7 h-7 rounded-lg '+e.bg+' flex items-center justify-center"><i class="fas '+e.icon+' '+e.color+' text-[10px]"></i></div><div class="flex-1 min-w-0"><div class="flex items-center justify-between gap-2"><span class="text-white text-xs font-semibold">'+e.label+'</span><span class="text-gray-500 text-[10px]">'+ubTimeAgo(e.time)+'</span></div><div class="text-gray-500 text-[10px] truncate mt-0.5">'+(e.amount?e.amount+' '+e.token+' · ':'')+(e.detail||'')+'</div></div><span class="text-[9px] font-bold px-1.5 py-0.5 rounded '+((e.status==='completed'||e.status==='paid')?'bg-green-900/30 text-green-400':e.status==='failed'?'bg-red-900/30 text-red-400':'bg-yellow-900/30 text-yellow-400')+'">'+e.status+'</span>'+((e.txHash&&e.source!=='agent')?'<a href="https://testnet.arcscan.app/tx/'+e.txHash+'" target="_blank" class="text-gray-600 hover:text-cyan-400"><i class="fas fa-external-link-alt text-[10px]"></i></a>':'')+'</div>').join('');}
function ubRenderActivity(){var el=ub$('ub-activity-list');if(!el)return;if(!ubState.ledger.length){el.innerHTML='<div class="text-center py-8 text-gray-600 text-sm"><i class="fas fa-inbox text-2xl mb-2 block"></i>No activity yet</div>';return;}el.innerHTML=ubState.ledger.slice(0,15).map(e=>'<div class="flex items-center gap-3 px-4 py-2.5 border-b border-gray-700/30 hover:bg-gray-800/20"><div class="w-7 h-7 rounded-lg '+e.bg+' flex items-center justify-center"><i class="fas '+e.icon+' '+e.color+' text-[10px]"></i></div><div class="flex-1 min-w-0"><div class="flex items-center justify-between gap-2"><span class="text-white text-xs font-semibold">'+e.label+'</span><span class="text-gray-500 text-[10px]">'+ubTimeAgo(e.time)+'</span></div><div class="text-gray-500 text-[10px] truncate mt-0.5">'+(e.amount?e.amount+' '+e.token+' · ':'')+(e.detail||'')+'</div></div>'+((e.txHash&&e.source!=='agent')?'<a href="https://testnet.arcscan.app/tx/'+e.txHash+'" target="_blank" class="text-gray-600 hover:text-cyan-400"><i class="fas fa-external-link-alt text-[10px]"></i></a>':'')+'</div>').join('');}

// ═══════════════════ TREASURY MANAGEMENT ═══════════════════
function ubRenderTreasury(){var el=ub$('ub-treasury-view');if(!el)return;var total=ubState.totals.usd;if(!total){el.innerHTML='<div class="text-center py-6 text-gray-600 text-xs">No treasury data — connect wallet</div>';return;}var bt=ubState.totals.byToken||{};var byNet=ubState.totals.byNetwork||{};var html='<div class="space-y-3"><div class="text-xs text-gray-400 mb-1">Allocation by Token</div>';for(var[t,v]of Object.entries(bt)){var pct=(v/total*100).toFixed(1);var tk=UB_TOKENS[t];html+='<div class="flex items-center gap-2"><span class="text-xs w-12 text-gray-400">'+(tk?tk.logo:'')+' '+t+'</span><div class="flex-1 h-2 bg-gray-700/50 rounded-full"><div class="h-full rounded-full bg-gradient-to-r from-green-500 to-emerald-500" style="width:'+pct+'%"></div></div><span class="text-[10px] text-gray-300 w-16 text-right">'+pct+'%</span></div>';}html+='<div class="text-xs text-gray-400 mt-4 mb-1">Allocation by Network</div>';for(var[nk,vv]of Object.entries(byNet)){var p2=(vv/total*100).toFixed(1);var net=UB_NETWORKS[nk];html+='<div class="flex items-center gap-2"><span class="text-xs w-20 text-gray-400">'+(net?net.icon:'')+' '+(net?net.name:nk)+'</span><div class="flex-1 h-2 bg-gray-700/50 rounded-full"><div class="h-full rounded-full bg-gradient-to-r from-blue-500 to-cyan-500" style="width:'+p2+'%"></div></div><span class="text-[10px] text-gray-300 w-16 text-right">'+p2+'%</span></div>';}html+='</div>';el.innerHTML=html;}

// ═══════════════════ FINANCIAL PROFILE ═══════════════════
function ubComputeProfile(){var p=ubState.profile;var total=ubState.totals.usd;p.totalValue=total;p.riskScore=total>1000?20:total>500?30:total>100?45:total>0?60:80;var txCount=ubState.analytics.txCount+ubState.agentLog.length+ubState.ledger.length;p.activityLevel=txCount>50?'high':txCount>10?'medium':'low';p.preferredNetwork='arc';for(var[nk,v]of Object.entries(ubState.totals.byNetwork||{})){if(v>(ubState.totals.byNetwork[p.preferredNetwork]||0))p.preferredNetwork=nk;} ubText('ub-profile-score',String(Math.max(0,100-p.riskScore)));ubText('ub-profile-level',p.activityLevel.charAt(0).toUpperCase()+p.activityLevel.slice(1));ubText('ub-profile-network',UB_NETWORKS[p.preferredNetwork]?.name||'Arc Testnet');ubText('ub-profile-since','Active');}

// ═══════════════════ COMPLIANCE / EXPORT ═══════════════════
function ubExportCSV(){if(!ubState.ledger.length){ubShowToast('No data to export','warning');return;}var csv='type,label,amount,token,detail,txHash,time,status,source\n';csv+=ubState.ledger.map(e=>[e.type,e.label,e.amount||'',e.token||'',(e.detail||'').replace(/,/g,' '),e.txHash||'',e.time||'',e.status||'',e.source||''].join(',')).join('\n');var blob=new Blob([csv],{type:'text/csv'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='execdaat_ledger_'+new Date().toISOString().slice(0,10)+'.csv';a.click();ubShowToast('CSV exported','success');URL.revokeObjectURL(url);}
function ubExportAudit(){var data={profile:ubState.profile,totals:ubState.totals,agentPerms:ubState.agents,invoiceCount:ubState.invoices.length,ruleCount:ubState.rules.length,ledgerCount:ubState.ledger.length,analytics:ubState.analytics,exportedAt:new Date().toISOString()};var blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='execdaat_audit_'+new Date().toISOString().slice(0,10)+'.json';a.click();ubShowToast('Audit report exported','success');URL.revokeObjectURL(url);}

// ═══════════════════ P2P CONTACTS ═══════════════════
function ubLoadContacts(){try{ubState.contacts=JSON.parse(localStorage.getItem('ub_contacts_v1')||'[]');}catch(_){ubState.contacts=[];}}
function ubSaveContacts(){try{localStorage.setItem('ub_contacts_v1',JSON.stringify(ubState.contacts.slice(0,30)));}catch(_){}}
function ubAddContact(){var addr=ub$('ub-contact-addr')?.value?.trim();var label=ub$('ub-contact-label')?.value?.trim();if(!addr||!/^0x[a-fA-F0-9]{40}$/.test(addr)){ubShowToast('Invalid address','warning');return;}ubState.contacts.push({address:addr,label:label||addr.slice(0,8),created:new Date().toISOString()});ubSaveContacts();ubRenderContacts();ubShowToast('Contact added','success');}
function ubRemoveContact(idx){ubState.contacts.splice(idx,1);ubSaveContacts();ubRenderContacts();}
function ubSendToContact(idx){var c=ubState.contacts[idx];if(!c)return;ubSetVal('ub-send-recipient',c.address);ubSetVal('ub-send-amount','');ubShow('ub-send-modal');}
function ubRenderContacts(){var el=ub$('ub-contact-list');if(!el)return;if(!ubState.contacts.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">No contacts yet</div>';return;}el.innerHTML=ubState.contacts.map((c,i)=>'<div class="flex items-center justify-between px-4 py-2 border-b border-gray-700/30 text-xs"><div><div class="text-white font-semibold">'+c.label+'</div><div class="text-gray-500 font-mono text-[10px]">'+c.address.slice(0,8)+'...'+c.address.slice(-6)+'</div></div><div class="flex items-center gap-1"><button onclick="ubSendToContact('+i+')" class="text-blue-400 hover:text-blue-300 text-[10px] px-2 py-1 bg-blue-900/20 rounded" title="Send"><i class="fas fa-paper-plane"></i></button><button onclick="ubRemoveContact('+i+')" class="text-red-400 hover:text-red-300 text-[10px] px-2 py-1 bg-red-900/20 rounded" title="Remove"><i class="fas fa-times"></i></button></div></div>').join('');}

// ═══════════════════ SMART ROUTER ═══════════════════
const SmartRouter={findBestRoute(amountUSD,pref){var r=[];for(const[k,b]of Object.entries(ubState.balances)){if(b.raw<=0n)continue;var tk=UB_TOKENS[b.symbol],n=UB_NETWORKS[b.network];if(!tk||!n)continue;var need=amountUSD/tk.priceUSD,he=b.usd>=amountUSD,fu=need*(tk.feeBps||5)/10000,gu=n.avgGas||0.001,tc=fu+gu;r.push({key:k,network:b.network,symbol:b.symbol,balance:b.human,balanceUSD:b.usd,token:tk,net:n,needed:need,hasEnough:he,feeUSD:fu,gasUSD:gu,totalCost:tc,score:(he?1000:0)+(pref===n.network?500:0)-tc*100+b.usd*0.01});}r.sort((a,b)=>b.score-a.score);return r;},getBest(a,p){return this.findBestRoute(a,p)[0]||null;},getComparison(a,p){return this.findBestRoute(a,p).slice(0,3);}};
const IntentEngine={parse(input){input=input.trim();var amt=null,tk='USDC',rec=null,act='send';var m=input.match(/(send|pay|transfer|bridge|swap)\s+(\d+(?:\.\d+)?)\s*(usdc|eurc|usyc)?\s*(?:to\s+)?(0x[a-fA-F0-9]{40}|\S+)/i);if(!m)m=input.match(/(\d+(?:\.\d+)?)\s*(usdc|eurc|usyc)?\s*(?:to\s+)?(0x[a-fA-F0-9]{40}|\S+)/i);if(m){act=(m[1]||'send').toLowerCase();if(act==='transfer')act='send';amt=parseFloat(m[2]||m[1]);tk=(m[3]||'usdc').toUpperCase();rec=m[4]||'';}return{action:act,amount:amt,token:tk,recipient:rec,original:input,valid:!!(amt&&amt>0&&rec)};},async execute(intent){if(!intent.valid)throw new Error('Invalid intent');var w=window.walletState?.address,p=window.walletState?.provider;if(!w||!p)throw new Error('Connect wallet');if(!window.ethers)throw new Error('ethers.js missing');var ep=new window.ethers.BrowserProvider(p),s=await ep.getSigner();var addr=intent.token==='USDC'?'0x3600000000000000000000000000000000000000':'0x89B50855Aa3bE2F677cD6303Cec089B5F319D72a';var dec=UB_TOKENS[intent.token]?.decimals||6,amtBN=window.ethers.parseUnits(intent.amount.toFixed(6),dec);var tk=new window.ethers.Contract(addr,UB_ERC20_ABI,s);var tx=await tk.transfer(intent.recipient,amtBN);var rc=await tx.wait();if(!rc||rc.status!==1)throw new Error('Reverted');ubAddPaymentToHistory(intent.amount,intent.token,intent.recipient,tx.hash,'completed');return{success:true,txHash:tx.hash,intent};}};

// ═══════════════════ AGENT PERMISSIONS ═══════════════════
function ubLoadAgentPerms(){try{var p=JSON.parse(localStorage.getItem('ub_agent_perms_v1')||'{}');ubState.agents=p;}catch(_){ubState.agents={};}for(var[id,a]of Object.entries(AGENT_REGISTRY)){if(!ubState.agents[id])ubState.agents[id]={enabled:true,maxAutoUSD:a.maxAutoUSD,dailyLimitUSD:a.dailyLimitUSD,dailyUsed:0,dailyReset:new Date().toDateString(),totalExecuted:0};}}
function ubSaveAgentPerms(){try{localStorage.setItem('ub_agent_perms_v1',JSON.stringify(ubState.agents));}catch(_){}}
function ubResetDailyUsage(){var today=new Date().toDateString();for(var[id,p]of Object.entries(ubState.agents)){if(p.dailyReset!==today){p.dailyUsed=0;p.dailyReset=today;}}ubSaveAgentPerms();}
function ubCheckAgentPermission(agentId,intent){var agent=AGENT_REGISTRY[agentId],perm=ubState.agents[agentId];if(!agent||!perm)return{allowed:false,needApproval:true,reason:'Agent not configured'};if(!perm.enabled)return{allowed:false,needApproval:true,reason:'Agent disabled'};if(!agent.capabilities.includes(intent.action))return{allowed:false,needApproval:true,reason:'Cannot perform '+intent.action};var risk=ubComputeRiskScore(intent);if(risk>80)return{allowed:false,needApproval:true,reason:'Risk too high ('+risk+')'};var eff=perm.maxAutoUSD||agent.maxAutoUSD;ubResetDailyUsage();if(intent.amount>eff)return{allowed:true,needApproval:true,reason:'Exceeds auto limit ('+eff+' USD)'};if((perm.dailyUsed||0)+intent.amount>(perm.dailyLimitUSD||agent.dailyLimitUSD))return{allowed:false,needApproval:true,reason:'Daily limit exceeded'};return{allowed:true,needApproval:false,riskScore:risk};}
function ubComputeRiskScore(intent){var s=0;if(intent.amount>500)s+=30;else if(intent.amount>100)s+=15;if(intent.recipient&&!/^0x[a-fA-F0-9]{40}$/.test(intent.recipient))s+=10;var t=ubState.totals.usd;if(t>0&&intent.amount/t>0.5)s+=25;if(ubState.analytics.txCount>50)s+=10;return Math.min(100,s);}
function ubRenderRiskBar(score){var c=score<=25?'bg-green-500':score<=50?'bg-yellow-500':score<=75?'bg-orange-500':'bg-red-500';return'<div class="w-full h-1.5 bg-gray-700/50 rounded-full"><div class="h-full rounded-full '+c+'" style="width:'+score+'%"></div></div>';}
function ubCreateAgentIntent(agentId,action,amount,token,recipient){var intent={id:'aint_'+Date.now().toString(36),agentId,action,amount,token:token||'USDC',recipient:recipient||'',created:new Date().toISOString(),status:'created'};var check=ubCheckAgentPermission(agentId,intent);intent.permissionCheck=check;intent.riskScore=check.riskScore||0;intent.status=check.allowed&&!check.needApproval?'approved':'pending_approval';intent.reason=check.reason||'';ubLogAgentActivity(agentId,'intent_created',intent);return intent;}
async function ubExecuteAgentIntent(intent){if(intent.status==='pending_approval'){var ok=await(new Promise(r=>{var ag=AGENT_REGISTRY[intent.agentId];var msg=(ag?ag.name:'Agent')+' wants to '+intent.action+' '+intent.amount+' '+intent.token+' → '+(intent.recipient||'').slice(0,10)+'...\nRisk: '+(intent.riskScore||0)+'/100\nReason: '+(intent.reason||'');if(window._showConfirm)window._showConfirm(msg,'Agent Approval').then(r);else r(window.confirm(msg));}));if(!ok){intent.status='rejected';ubLogAgentActivity(intent.agentId,'intent_rejected',intent);return{success:false,reason:'User rejected'};}}intent.status='executing';ubLogAgentActivity(intent.agentId,'executing',intent);var w=window.walletState?.address,p=window.walletState?.provider;if(!w||!p)throw new Error('Wallet not connected');try{if(!window.ethers)throw new Error('ethers.js missing');var ep=new window.ethers.BrowserProvider(p),s=await ep.getSigner();var addr=intent.token==='USDC'?'0x3600000000000000000000000000000000000000':'0x89B50855Aa3bE2F677cD6303Cec089B5F319D72a';var dec=UB_TOKENS[intent.token]?.decimals||6,amtBN=window.ethers.parseUnits(intent.amount.toFixed(6),dec);var tk=new window.ethers.Contract(addr,UB_ERC20_ABI,s);var tx=await tk.transfer(intent.recipient,amtBN);var rc=await tx.wait();if(!rc||rc.status!==1)throw new Error('Reverted');var perm=ubState.agents[intent.agentId];if(perm){perm.dailyUsed=(perm.dailyUsed||0)+intent.amount;perm.totalExecuted=(perm.totalExecuted||0)+1;ubSaveAgentPerms();}ubAddPaymentToHistory(intent.amount,intent.token,intent.recipient,tx.hash,'completed');intent.status='completed';intent.txHash=tx.hash;ubLogAgentActivity(intent.agentId,'completed',intent);ubDispatchEvent('agent:executed',{agentId:intent.agentId,intent,txHash:tx.hash});return{success:true,txHash:tx.hash,intent};}catch(e){intent.status='failed';intent.error=e.shortMessage||e.message||'Unknown';ubLogAgentActivity(intent.agentId,'failed',intent);throw e;}}
function ubLogAgentActivity(agentId,action,data){var entry={agentId,action,timestamp:new Date().toISOString(),summary:data.amount?data.amount+' '+data.token:'',details:JSON.stringify(data).slice(0,200)};ubState.agentLog.unshift(entry);if(ubState.agentLog.length>100)ubState.agentLog.length=100;try{localStorage.setItem('ub_agent_log_v1',JSON.stringify(ubState.agentLog.slice(0,50)));}catch(_){}ubRenderAgentLog();ubRenderAgentCards();}
function ubLoadAgentLog(){try{ubState.agentLog=JSON.parse(localStorage.getItem('ub_agent_log_v1')||'[]');}catch(_){ubState.agentLog=[];}}
function ubRenderAgentLog(){var el=ub$('ub-agent-log-list');if(!el)return;if(!ubState.agentLog.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">No activity</div>';return;}el.innerHTML=ubState.agentLog.slice(0,15).map(e=>{var ag=AGENT_REGISTRY[e.agentId];if(!ag)return'';var ac={intent_created:'text-blue-400',executing:'text-yellow-400',completed:'text-green-400',failed:'text-red-400',intent_rejected:'text-gray-500'};return'<div class="flex items-center gap-2 px-4 py-2 border-b border-gray-700/30 text-xs"><i class="fas '+ag.icon+' '+ag.color+' w-4 text-center"></i><span class="text-white font-semibold">'+ag.name+'</span><span class="'+((ac[e.action]||'text-gray-500')+' text-[10px]')+'">'+e.action.replace(/_/g,' ')+'</span><span class="text-gray-500 text-[10px] ml-auto">'+(e.timestamp||'').slice(11,19)+'</span></div>';}).join('');}

function ubRunAgentSuggestion(agentId){var ag=AGENT_REGISTRY[agentId];if(!ag)return;var t=ubState.totals.usd,s='';switch(agentId){case'payment':s=t<10?'Balance low. Deposit USDC.':'Ready for auto payments up to '+ubFormatUSD(ubState.agents.payment?.maxAutoUSD||100)+'.';break;case'swap':s='Swap USDC ↔ EURC via the Dex tab. Fee: 0.3%.';break;case'bridge':s='Bridge via CCTP: Arc ↔ Ethereum Sepolia. Use Quick Actions.';break;case'yield':s='Add liquidity to EURC/USDC pool. Earn 0.3% swap fees.';break;case'treasury':s=t>1000?'Significant treasury ('+ubFormatUSD(t)+'). Enable rules.':'Build treasury to unlock features.';break;case'analyst':s='📊 '+ubState.analytics.txCount+' tx total. Sent: '+ubFormatUSD(ubState.analytics.totalSent)+'.';break;case'liquidity':s=ubLiquidityAgentSuggestion();break;default:s='Agent ready.';}ubHTML('ub-agent-suggestion','<div class="text-xs text-gray-400"><i class="fas '+ag.icon+' '+ag.color+' mr-1.5"></i>'+ag.name+': '+s+'</div>');ubDispatchEvent('agent:suggested',{agentId,suggestion:s});}
function ubAnalyzeWallet(){var w=window.walletState?.address;var t=ubState.totals.usd;var entries=Object.entries(ubState.balances).filter(([,b])=>b.raw>0n);var tl=entries.map(([,b])=>b.symbol+' on '+UB_NETWORKS[b.network].name).join(', ');var ic=ubState.invoices.filter(i=>i.status==='pending'||i.status==='created').length;var rc=ubState.rules.length;var r='<div class="space-y-2 text-xs">';r+='<div class="flex justify-between"><span class="text-gray-500">Wallet</span><span class="text-white font-mono">'+(w?w.slice(0,8)+'...':'—')+'</span></div>';r+='<div class="flex justify-between"><span class="text-gray-500">Total Value</span><span class="text-green-400 font-bold">'+ubFormatUSD(t)+'</span></div>';r+='<div class="flex justify-between"><span class="text-gray-500">Active Tokens</span><span class="text-white">'+(tl||'None')+'</span></div>';r+='<div class="flex justify-between"><span class="text-gray-500">Pending</span><span class="text-yellow-400">'+ic+' invoices</span></div>';r+='<div class="flex justify-between"><span class="text-gray-500">LP Position</span><span class="text-cyan-400">'+(ubState.liquidity.poolShare>0?ubState.liquidity.poolShare.toFixed(2)+'% pool share':'None')+'</span></div>';r+='<div class="flex justify-between"><span class="text-gray-500">AMM TVL</span><span class="text-white">'+(ubState.liquidity.pool.loaded?ubFormatUSD(ubState.liquidity.pool.tvl):'Loading...')+'</span></div>';r+='<div class="border-t border-gray-700/40 pt-2 mt-2">';r+=t===0?'<span class="text-gray-500">💡 Deposit USDC or EURC to activate FinOS.</span>':t<100?'<span class="text-yellow-400">⚠ Low balance. Agents operate within strict limits.</span>':'<span class="text-green-400">✅ FinOS operational. All systems nominal.</span>';r+='</div></div>';return r;}

function ubRenderAgentCards(){var el=ub$('ub-agent-cards');if(!el)return;el.innerHTML=Object.entries(AGENT_REGISTRY).map(([id,a])=>{var perm=ubState.agents[id]||{};var en=perm.enabled!==false;var du=perm.dailyUsed||0,ma=perm.maxAutoUSD||a.maxAutoUSD,dl=perm.dailyLimitUSD||a.dailyLimitUSD;var lc=ubState.agentLog.filter(l=>l.agentId===id).length;return'<div class="bg-gray-900/80 border '+(en?'border-gray-700/50 hover:border-'+a.color.replace('text-','')+'/40':'border-gray-700/30 opacity-60')+' rounded-xl p-4 transition-all cursor-pointer" onclick="ubRunAgentSuggestion(\''+id+'\')"><div class="flex items-center justify-between mb-3"><div class="flex items-center gap-2.5"><div class="w-8 h-8 rounded-lg '+a.bg+' border border-'+a.color.replace('text-','')+'/30 flex items-center justify-center"><i class="fas '+a.icon+' '+a.color+' text-xs"></i></div><div><div class="text-white font-semibold text-xs">'+a.name+'</div><div class="text-gray-500 text-[10px]">'+a.desc+'</div></div></div><div class="flex items-center gap-1.5"><span class="w-1.5 h-1.5 rounded-full '+(en?'bg-green-400':'bg-gray-600')+'"></span><span class="text-[10px] '+(en?'text-green-400':'text-gray-500')+'">'+(en?'Active':'Off')+'</span><button onclick="event.stopPropagation();ubOpenAgentPerms(\''+id+'\')" class="text-gray-600 hover:text-gray-400 ml-1" title="Configure"><i class="fas fa-cog text-[10px]"></i></button></div></div><div class="grid grid-cols-2 gap-2 text-[10px]"><div class="bg-gray-800/50 rounded-lg p-2"><div class="text-gray-600">Auto Limit</div><div class="text-white font-bold">'+(ma===0?'Manual':ubFormatUSD(ma))+'</div></div><div class="bg-gray-800/50 rounded-lg p-2"><div class="text-gray-600">Daily Cap</div><div class="text-white font-bold">'+ubFormatUSD(dl)+'</div></div><div class="bg-gray-800/50 rounded-lg p-2"><div class="text-gray-600">Used Today</div><div class="text-yellow-400 font-bold">'+ubFormatUSD(du)+'</div></div><div class="bg-gray-800/50 rounded-lg p-2"><div class="text-gray-600">Risk</div><div class="font-bold '+(a.risk==='low'?'text-green-400':a.risk==='medium'?'text-yellow-400':'text-red-400')+'">'+a.risk.toUpperCase()+'</div></div></div><div class="mt-2 flex items-center gap-2">'+ubRenderRiskBar(a.risk==='low'?15:a.risk==='medium'?40:70)+'<span class="text-[9px] text-gray-600">'+lc+' events</span></div></div>';}).join('');}

// ═══════════════════ INVOICES ═══════════════════
function ubLoadInvoices(){try{ubState.invoices=JSON.parse(localStorage.getItem('ub_invoices_v2')||'[]');}catch(_){ubState.invoices=[];}}
function ubSaveInvoices(){try{localStorage.setItem('ub_invoices_v2',JSON.stringify(ubState.invoices.slice(0,50)));}catch(_){}}
function ubCreateInvoice(amount,token,note,recipient){ubLoadInvoices();var inv={id:'inv_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),amount:parseFloat(amount),token:token||'USDC',note:note||'',recipient:recipient||window.walletState?.address||'',status:'created',lifecycle:['created'],created:new Date().toISOString(),sentAt:null,paidBy:null,paidTx:null,settledAt:null};ubState.invoices.unshift(inv);ubSaveInvoices();ubDispatchEvent('invoice:created',inv);ubRenderInvoices();return inv;}
function ubUpdateInvoiceStatus(id,s){var inv=ubState.invoices.find(i=>i.id===id);if(!inv)return;inv.status=s;inv.lifecycle.push(s);var now=new Date().toISOString();if(s==='sent')inv.sentAt=now;if(s==='paid')inv.settledAt=now;if(s==='cancelled')inv.cancelledAt=now;ubSaveInvoices();ubDispatchEvent('invoice:'+s,inv);ubRenderInvoices();}
function ubMarkInvoicePaid(id,payer,txHash){var inv=ubState.invoices.find(i=>i.id===id);if(!inv)return;inv.status='paid';inv.paidBy=payer;inv.paidTx=txHash;inv.settledAt=new Date().toISOString();if(!inv.lifecycle.includes('paid'))inv.lifecycle.push('paid');ubSaveInvoices();ubDispatchEvent('invoice:paid',inv);ubRenderInvoices();}
function ubRenderInvoices(){var el=ub$('ub-invoice-list');if(!el)return;if(!ubState.invoices.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">No requests yet</div>';return;}el.innerHTML=ubState.invoices.slice(0,6).map(inv=>{var cc={created:'text-gray-400 bg-gray-800/30',sent:'text-blue-400 bg-blue-900/20',paid:'text-green-400 bg-green-900/20',cancelled:'text-red-400 bg-red-900/20'}[inv.status]||'';return'<div class="flex items-center justify-between px-4 py-2.5 border-b border-gray-700/30 hover:bg-gray-800/20"><div class="flex items-center gap-2.5"><div class="w-7 h-7 rounded-lg '+cc+' flex items-center justify-center"><i class="fas '+(inv.status==='paid'?'fa-check':'fa-clock')+' text-xs"></i></div><div><div class="text-white text-xs font-semibold">'+inv.amount+' '+inv.token+(inv.note?' · '+inv.note:'')+'</div><div class="text-gray-500 text-[10px]">'+inv.id.slice(0,10)+'</div></div></div><span class="text-[9px] font-bold px-2 py-0.5 rounded-full border '+cc+'">'+inv.status.toUpperCase()+'</span></div>';}).join('');}
function ubRenderRules(){var el=ub$('ub-rules-list');if(!el)return;if(!ubState.rules.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">No automated rules</div>';return;}el.innerHTML=ubState.rules.map(r=>'<div class="flex items-center justify-between px-4 py-2 border-b border-gray-700/30"><div class="flex items-center gap-2.5"><span class="'+(r.enabled?'text-green-400':'text-gray-600')+'"><i class="fas fa-'+(r.enabled?'play':'pause')+' text-[10px]"></i></span><div><span class="text-white text-xs font-semibold">'+(r.type==='recurring'?'🔁 '+r.schedule:'⚡ Once')+' '+r.amount+' '+r.token+' → '+(r.recipient||'').slice(0,8)+'...</span></div></div><div class="flex items-center gap-1"><button onclick="ubToggleRule(\''+r.id+'\')" class="text-gray-600 hover:text-gray-400 text-[10px]">'+(r.enabled?'Disable':'Enable')+'</button><button onclick="ubDeleteRule(\''+r.id+'\')" class="text-gray-600 hover:text-red-400 text-[10px]"><i class="fas fa-trash"></i></button></div></div>').join('');}
function ubLoadRules(){try{ubState.rules=JSON.parse(localStorage.getItem('ub_rules_v1')||'[]');}catch(_){ubState.rules=[];}}
function ubSaveRules(){try{localStorage.setItem('ub_rules_v1',JSON.stringify(ubState.rules.slice(0,20)));}catch(_){}}
function ubCreateRule(type,amount,token,recipient,schedule){ubLoadRules();var r={id:'rule_'+Date.now().toString(36),type,amount,token,recipient,schedule,enabled:true,created:new Date().toISOString()};ubState.rules.push(r);ubSaveRules();ubDispatchEvent('rule:created',r);ubRenderRules();return r;}
function ubToggleRule(id){var r=ubState.rules.find(x=>x.id===id);if(!r)return;r.enabled=!r.enabled;ubSaveRules();ubRenderRules();}
function ubDeleteRule(id){ubState.rules=ubState.rules.filter(x=>x.id!==id);ubSaveRules();ubRenderRules();}

// ═══════════════════ ANALYTICS ═══════════════════
function ubComputeAnalytics(){var ts=0,tc=0,bt={},bd={};try{var bh=JSON.parse(localStorage.getItem('bridge_history_v1')||'[]');bh.forEach(h=>{if(h.amount){ts+=parseFloat(h.amount)||0;tc++;bt[h.token||'USDC']=(bt[h.token||'USDC']||0)+(parseFloat(h.amount)||0);var d=(h.timestamp||'').slice(0,10);bd[d]=(bd[d]||0)+1;}});var ph=JSON.parse(localStorage.getItem('arc_pay_history')||'[]');ph.forEach(p=>{if(p.amount){ts+=parseFloat(p.amount)||0;tc++;bt[p.token||'USDC']=(bt[p.token||'USDC']||0)+(parseFloat(p.amount)||0);var d=(p.timestamp||p.date||'').slice(0,10);bd[d]=(bd[d]||0)+1;}});}catch(_){}ubState.analytics={totalSent:ts,totalReceived:0,txCount:tc,byToken:bt,byDay:bd};}
function ubRenderAnalytics(){var a=ubState.analytics;ubText('ub-analytics-total',ubFormatUSD(a.totalSent));ubText('ub-analytics-count',String(a.txCount));var days=Object.keys(a.byDay).sort().slice(-7);var mc=Math.max(1,...Object.values(a.byDay));var el=ub$('ub-analytics-bars');if(!el)return;if(!days.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-[10px]">No data</div>';return;}el.innerHTML=days.map(d=>{var c=a.byDay[d]||0;var h=Math.max(8,(c/mc)*60);return'<div class="flex flex-col items-center gap-1"><div class="w-6 rounded-t bg-green-500/60" style="height:'+h+'px" title="'+d+': '+c+' tx"></div><span class="text-[9px] text-gray-600">'+(d.slice(5)||d)+'</span></div>';}).join('');}

// ═══════════════════ MAIN REFRESH ═══════════════════
async function ubRefresh(){try{var w=window.walletState?.address;if(!w){ubShowEmpty('Connect wallet');return;}ubState.loading=true;ubState.error=null;ubRenderLoading();var bal={};var ws=window.walletState;if(ws.usdcBalance){var v=parseFloat(ws.usdcBalance);bal['arc:USDC']={network:'arc',symbol:'USDC',raw:BigInt(Math.floor(v*1e6)),human:v,usd:v*1.00};}if(ws.eurcBalance){var ve=parseFloat(ws.eurcBalance);bal['arc:EURC']={network:'arc',symbol:'EURC',raw:BigInt(Math.floor(ve*1e6)),human:ve,usd:ve*1.09};}var tu=0;for(var b of Object.values(bal))tu+=b.usd;ubState.balances=bal;ubState.totals.usd=tu;ubState.loaded=true;ubState.loading=false;ubLoadInvoices();ubLoadRules();ubLoadAgentPerms();ubLoadAgentLog();ubLoadContacts();ubFetchUnifiedLedger();ubComputeAnalytics();ubRender();ubComputeProfile();try{var eurcR=await ubFetchTokenBalance('arc','EURC',w);if(eurcR>0n){var eh=Number(eurcR)/1e6;bal['arc:EURC']={network:'arc',symbol:'EURC',raw:eurcR,human:eh,usd:eh*1.09};}var usycR=await ubFetchTokenBalance('arc','USYC',w);if(usycR>0n){var uh=Number(usycR)/1e6;bal['arc:USYC']={network:'arc',symbol:'USYC',raw:usycR,human:uh,usd:uh*1.00};}tu=0;for(var b of Object.values(bal))tu+=b.usd;ubState.balances=bal;ubState.totals.usd=tu;ubRenderBalancesOnly();}catch(_){}var xtasks=[];for(var nk of['sepolia','arbsepolia','basesepolia','optsepolia','polygonamoy'])xtasks.push((async()=>{var r=await ubFetchTokenBalance(nk,'USDC',w);if(r>0n){var h=Number(r)/1e6;bal[nk+':USDC']={network:nk,symbol:'USDC',raw:r,human:h,usd:h*1.00};}})());Promise.allSettled(xtasks).then(()=>{var t2=0;for(var b of Object.values(bal))t2+=b.usd;ubState.balances=bal;ubState.totals.usd=t2;ubRenderBalancesOnly();});ubFetchPoolState().then(()=>{ubFetchLPPosition().then(()=>{ubRenderLiquidityDashboard();ubRenderLPPosition();});});if(!ubState._interval)ubState._interval=setInterval(()=>{if(document.hidden)return;var t=document.getElementById('tab-content-unifiedbalance');if(t&&!t.classList.contains('hidden'))ubRefreshSilent();},60000);}catch(e){console.error('[FinOS]',e);ubState.error=e.message;ubState.loading=false;ubRenderError();}}
async function ubRefreshSilent(){var w=window.walletState?.address;if(!w)return;try{var bal={};for(var[sm,tk]of Object.entries(UB_TOKENS))for(var nk of tk.networks){var r=await ubFetchTokenBalance(nk,sm,w);if(r>0n||nk==='arc'){var h=Number(r)/10**tk.decimals;bal[nk+':'+sm]={network:nk,symbol:sm,raw:r,human:h,usd:h*tk.priceUSD};}}var tu=0;for(var b of Object.values(bal))tu+=b.usd;ubState.balances=bal;ubState.totals.usd=tu;ubRenderBalancesOnly();}catch(_){}}

function ubRender(){ubRenderAccountCard();ubRenderBalances();ubRenderNetworkChips();ubRenderAgentCards();ubRenderTreasury();ubRenderLedgerSection();ubRenderActivity();ubRenderInvoices();ubRenderRules();ubRenderAgentLog();ubComputeAnalytics();ubRenderNotifications();ubRenderSDKRef();}
function ubRenderLoading(){ubText('ub-account-total','—');ubHTML('ub-token-table-body',ubSpinner('Fetching...'));ubHTML('ub-ledger-list','<div class="text-center py-8 text-gray-600 text-sm"><i class="fas fa-spinner fa-spin text-2xl mb-2 block"></i>Loading ledger...</div>');ubHTML('ub-agent-log-list','<div class="text-center py-4 text-gray-600 text-xs"><i class="fas fa-spinner fa-spin mb-1 block"></i>Loading...</div>');ubHTML('ub-agent-cards','<div class="col-span-full text-center py-8 text-gray-600 text-xs"><i class="fas fa-spinner fa-spin mb-2 block"></i>Loading agents...</div>');ubHTML('ub-treasury-view','<div class="text-center py-4 text-gray-600 text-xs"><i class="fas fa-spinner fa-spin mb-1 block"></i>Loading...</div>');ubHTML('ub-invoice-list','<div class="text-center py-4 text-gray-600 text-xs">Loading...</div>');ubHTML('ub-rules-list','<div class="text-center py-4 text-gray-600 text-xs">Loading...</div>');ubHTML('ub-network-chips','<span class="text-[10px] text-gray-600 animate-pulse">Loading...</span>');ubHTML('ub-liquidity-dash','<div class="text-center py-4 text-gray-600 text-xs"><i class="fas fa-spinner fa-spin mb-1 block"></i>Loading...</div>');ubHTML('ub-lp-position','<div class="text-center py-4 text-gray-600 text-xs"><i class="fas fa-spinner fa-spin mb-1 block"></i>Loading...</div>');ubHTML('ub-notif-list','<div class="text-center py-4 text-gray-600 text-xs">Loading...</div>');ubHTML('ub-sdk-content','<div class="text-center py-4 text-gray-600 text-xs">Loading...</div>');}
function ubSpinner(m){return'<tr><td colspan="5" class="py-8 text-center"><i class="fas fa-spinner fa-spin text-green-400 text-xl mb-2 block"></i><span class="text-gray-500 text-sm">'+m+'</span></td></tr>';}
function ubRenderError(){ubHTML('ub-token-table-body','<tr><td colspan="5" class="py-8 text-center"><i class="fas fa-exclamation-triangle text-red-400 text-xl mb-2 block"></i><span class="text-red-400 text-sm">'+ubState.error+'</span></td></tr>');ubText('ub-account-total','Error');}
function ubShowEmpty(msg){ubText('ub-account-total','$0.00');ubText('ub-account-addr',window.walletState?.address?(window.walletState.address.slice(0,6)+'...'+window.walletState.address.slice(-4)):'—');ubHTML('ub-token-table-body','<tr><td colspan="5" class="py-10 text-center"><i class="fas fa-wallet text-gray-700 text-3xl mb-3 block"></i><span class="text-gray-500 text-sm">'+(msg||'No assets')+'</span></td></tr>');ubHTML('ub-ledger-list','<div class="text-center py-8 text-gray-600 text-sm"><i class="fas fa-book text-2xl mb-2 block"></i>Ledger empty</div>');}
function ubRenderAccountCard(){var w=window.walletState?.address;ubText('ub-account-total',ubFormatUSD(ubState.totals.usd));if(w){ubText('ub-account-addr',w.slice(0,6)+'...'+w.slice(-4));ubText('ub-account-addr-full',w);}}
function ubRenderBalancesOnly(){ubRenderAccountCard();ubRenderBalances();}
