function ubDetailBringToArc(){var nk=ubState._detailNetKey,sym=ubState._detailSym||'USDC';if(nk==='arc'){if(typeof ubShowToast==='function')ubShowToast('Already on Arc','info');return;}ubCloseDetail();if(typeof switchTab==='function')switchTab('bridge');var map={sepolia:'sepolia',arbsepolia:'arbsepolia',basesepolia:'basesepolia',optsepolia:'optsepolia',polygonamoy:'polygonAmoy',arc:'arc'};var fromKey=map[nk]||nk;var tries=0;var iv=setInterval(function(){tries++;var ok=false;try{if(typeof window.xbSetTo==='function'&&typeof window.xbSetFrom==='function'){window.xbSetTo('arc');window.xbSetFrom(fromKey);ok=true;}}catch(_){}if(ok||tries>=24)clearInterval(iv);},250);}
