function ubOnSendAmountChange(){var amt=parseFloat(ub$('ub-send-amount')?.value||'0');if(!amt||amt<=0){ubHide('ub-send-route-detail');return;}ubShow('ub-send-route-detail');var routes=SmartRouter.getComparison(amt,'arc');if(routes.length){var best=routes[0];ubHTML('ub-send-route-info',best.token.logo+' <b>'+best.symbol+'</b> via '+best.net.name+' · Fee ~$'+best.totalCost.toFixed(4));ubSetVal('ub-send-auto-token',best.symbol);ubHTML('ub-send-comparison',routes.map((r,i)=>'<div class="flex justify-between text-[10px] py-0.5 '+(i===0?'text-green-400':'text-gray-500')+'"><span>'+r.token.logo+' '+r.symbol+' via '+r.net.icon+' '+r.net.name+'</span><span>Fee ~$'+r.totalCost.toFixed(4)+(r.hasEnough?'':' ⚠')+'</span></div>').join(''));}else{ubText('ub-send-route-info','No route');ubText('ub-send-comparison','');}}
async function ubExecuteSend(){if(ubState._sending)return;var w=window.walletState?.address,p=window.walletState?.provider;if(!w||!p){ubShowToast('Connect wallet','warning');return;}var rec=ub$('ub-send-recipient').value.trim(),amt=ub$('ub-send-amount').value.trim(),sym=ub$('ub-send-auto-token')?.value||'USDC';if(!rec||!/^0x[a-fA-F0-9]{40}$/.test(rec)){ubText('ub-send-status','Invalid address');return;}if(!amt||parseFloat(amt)<=0){ubText('ub-send-status','Enter amount');return;}ubState._sending=true;ubText('ub-send-status','⏳ Preparing...');var btn=ub$('ub-send-execute-btn');if(btn)btn.disabled=true;try{if(!window.ethers)throw new Error('ethers.js missing');var ep=new window.ethers.BrowserProvider(p),s=await ep.getSigner();var addr=sym==='USDC'?'0x3600000000000000000000000000000000000000':'0x89B50855Aa3bE2F677cD6303Cec089B5F319D72a';var dec=UB_TOKENS[sym]?.decimals||6,amtBN=window.ethers.parseUnits(amt,dec);var tk=new window.ethers.Contract(addr,UB_ERC20_ABI,s);ubText('ub-send-status','📝 Confirm...');var tx=await tk.transfer(rec,amtBN);ubText('ub-send-status','⏳ '+tx.hash.slice(0,14)+'...');var rc=await tx.wait();if(!rc||rc.status!==1)throw new Error('Reverted');ubAddPaymentToHistory(parseFloat(amt),sym,rec,tx.hash,'completed');ubText('ub-send-status','✅ Sent! <a href="https://testnet.arcscan.app/tx/'+tx.hash+'" target="_blank" class="underline text-cyan-400">View</a>');ubShowToast('✅ Sent '+amt+' '+sym,'success');ubDispatchEvent('payment:executed',{amount:parseFloat(amt),token:sym,recipient:rec,txHash:tx.hash});setTimeout(()=>{ubRefresh();ubCloseSend();},2500);}catch(e){var m=e.code===4001||(e.message||'').includes('rejected')?'Rejected':'Failed: '+(e.shortMessage||e.message||'').slice(0,60);ubText('ub-send-status','❌ '+m);}finally{ubState._sending=false;if(btn)btn.disabled=false;}}
function ubAddPaymentToHistory(amount,token,recipient,txHash,status){try{var ph=JSON.parse(localStorage.getItem('arc_pay_history')||'[]');ph.unshift({amount,token,to:recipient,txHash,status,timestamp:new Date().toISOString()});localStorage.setItem('arc_pay_history',JSON.stringify(ph.slice(0,50)));}catch(_){}}
