// ═══════════════════ GLOBAL LIQUIDITY NETWORK ═══════════════════
const UB_AMM_ADDR='0x3148E2807F172D1cC354F35fB4fC4104e8b6b561';
const UB_AMM_ABI=['function getReserves() view returns (uint256,uint256)','function totalSupply() view returns (uint256)','function balanceOf(address) view returns (uint256)','function tokenA() view returns (address)','function tokenB() view returns (address)'];
const UB_LP_TOKEN={EURC:'0x89B50855Aa3bE2F677cD6303Cec089B5F319D72a',USDC:'0x3600000000000000000000000000000000000000'};

// Add liquidity state
ubState.liquidity={pool:{reserveA:0n,reserveB:0n,totalSupply:0n,priceEURC:0,priceUSDC:0,tvl:0,loaded:false},lpBalance:0n,lpUSD:0,poolShare:0};

async function ubFetchPoolState(){try{var rpc=UB_NETWORKS.arc.rpc;var[ra,rb]=await Promise.all([ubEthCall(rpc,UB_AMM_ADDR,'0x0902f1ac'),ubEthCall(rpc,UB_AMM_ADDR,'0x8b7b5b5c')]);var ts=await ubEthCall(rpc,UB_AMM_ADDR,'0x18160ddd');ra=ra&&ra!=='0x'?BigInt(ra):0n;rb=rb&&rb!=='0x'?BigInt(rb):0n;ts=ts&&ts!=='0x'?BigInt(ts):0n;var raH=Number(ra)/1e6,rbH=Number(rb)/1e6;ubState.liquidity.pool={reserveA:ra,reserveB:rb,totalSupply:ts,priceEURC:raH>0?rbH/raH:0,priceUSDC:rbH>0?raH/rbH:0,tvl:raH+rbH,loaded:true};}catch(e){console.warn('[Liq] Pool fetch failed:',e.message);ubState.liquidity.pool.loaded=false;}}
async function ubFetchLPPosition(){var w=window.walletState?.address;if(!w||!ubState.liquidity.pool.loaded)return;try{var balSel='0x70a08231',padded='0x'+w.replace('0x','').toLowerCase().padStart(64,'0');var h=await ubEthCall(UB_NETWORKS.arc.rpc,UB_AMM_ADDR,balSel+padded.slice(2));var lp=BigInt(h||'0x0');var lpHuman=Number(lp)/1e6;var ts=Number(ubState.liquidity.pool.totalSupply)/1e6;var share=ts>0?(lpHuman/ts*100):0;var tvl=ubState.liquidity.pool.tvl;ubState.liquidity.lpBalance=lp;ubState.liquidity.lpUSD=share*tvl/100;ubState.liquidity.poolShare=share;}catch(e){console.warn('[Liq] LP fetch failed:',e.message);}}

function ubRenderLiquidityDashboard(){var p=ubState.liquidity.pool;var el=ub$('ub-liquidity-dash');if(!el)return;if(!p.loaded){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">Loading pool data from AMM...</div>';return;}var tvl=ubFormatUSD(p.tvl);el.innerHTML='<div class="grid grid-cols-2 sm:grid-cols-4 gap-2"><div class="bg-gray-800/50 rounded-lg p-3 text-center"><div class="text-[10px] text-gray-500 uppercase mb-1">TVL</div><div class="text-white font-bold text-sm">'+tvl+'</div></div><div class="bg-gray-800/50 rounded-lg p-3 text-center"><div class="text-[10px] text-gray-500 uppercase mb-1">Reserves</div><div class="text-white font-bold text-xs">💶 '+(Number(p.reserveA)/1e6).toLocaleString(void 0,{maximumFractionDigits:0})+' EURC</div></div><div class="bg-gray-800/50 rounded-lg p-3 text-center"><div class="text-[10px] text-gray-500 uppercase mb-1">Reserves</div><div class="text-white font-bold text-xs">💵 '+(Number(p.reserveB)/1e6).toLocaleString(void 0,{maximumFractionDigits:0})+' USDC</div></div><div class="bg-gray-800/50 rounded-lg p-3 text-center"><div class="text-[10px] text-gray-500 uppercase mb-1">Price</div><div class="text-white font-bold text-xs">1 EURC = '+p.priceEURC.toFixed(4)+' USDC</div></div></div>';}

function ubRenderLPPosition(){var l=ubState.liquidity;var el=ub$('ub-lp-position');if(!el)return;var w=window.walletState?.address;if(!w||!l.pool.loaded){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">Connect wallet to view LP position</div>';return;}if(l.lpBalance===0n){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs"><i class="fas fa-tint text-gray-700 text-lg mb-1 block"></i>No LP position<br><a href="#" onclick="switchTab(\'dex\')" class="text-cyan-400 underline text-[10px]">Add liquidity in Dex tab</a></div>';return;}el.innerHTML='<div class="space-y-2"><div class="flex justify-between text-xs"><span class="text-gray-500">LP Balance</span><span class="text-white font-mono font-bold">'+(Number(l.lpBalance)/1e6).toFixed(4)+' LP</span></div><div class="flex justify-between text-xs"><span class="text-gray-500">Value (USD)</span><span class="text-green-400 font-bold">'+ubFormatUSD(l.lpUSD)+'</span></div><div class="flex justify-between text-xs"><span class="text-gray-500">Pool Share</span><span class="text-cyan-400 font-bold">'+l.poolShare.toFixed(4)+'%</span></div><div class="flex justify-between text-xs"><span class="text-gray-500">Est. Returns</span><span class="text-yellow-400 font-bold">~'+(l.poolShare*0.003*365*100).toFixed(2)+'% APR</span></div></div>';}

// ─── Liquidity Router: find best execution path ─────────────────────────
const LiquidityRouter={analyze(amountIn,fromToken,toToken){var routes=[];var p=ubState.liquidity.pool;if(p.loaded&&p.reserveA>0n&&p.reserveB>0n){var isEURCtoUSDC=fromToken==='EURC'&&toToken==='USDC';var rIn=isEURCtoUSDC?p.reserveA:p.reserveB,rOut=isEURCtoUSDC?p.reserveB:p.reserveA;var rawIn=BigInt(Math.floor(amountIn*1e6));var fee=rawIn*3n/1000n;var rawOut=(rOut*(rawIn-fee))/(rIn+(rawIn-fee));var outHuman=Number(rawOut)/1e6;var price=isEURCtoUSDC?(Number(rOut)/Number(rIn)):(Number(rIn)/Number(rOut));var ideal=amountIn*price;var impact=ideal>0?((ideal-outHuman)/ideal*100):0;routes.push({type:'AMM',pool:'EURC/USDC',output:outHuman,impact,fee:amountIn*0.003,cost:amountIn*0.003,score:outHuman-impact*0.1,details:'x·y=k pool, 0.3% fee'});}for(var[k,b]of Object.entries(ubState.balances)){if(b.raw<=0n)continue;var tk=UB_TOKENS[b.symbol];if(toToken&&tk.symbol!==toToken)continue;routes.push({type:'Wallet',network:UB_NETWORKS[b.network].name,token:b.symbol,balance:b.human,output:b.human,cost:0,score:b.human,details:'Direct wallet balance'});}routes.sort((a,b)=>b.score-a.score);return routes;}};

// ─── Liquidity Agent suggestion ──────────────────────────────────────────
function ubLiquidityAgentSuggestion(){var l=ubState.liquidity;var p=l.pool;var t=ubState.totals.usd;var s='';if(!p.loaded){s='Pool data not yet loaded. Connect wallet and refresh.';}else if(l.lpBalance>0n&&l.poolShare>0.1){s='You hold '+l.poolShare.toFixed(2)+'% of the EURC/USDC pool. Consider rebalancing or compounding rewards.';}else if(t>10&&l.lpBalance===0n){s='Your wallet has '+ubFormatUSD(t)+'. Add liquidity to the EURC/USDC pool to earn 0.3% swap fees.';}else{s='EURC/USDC AMM pool: '+(Number(p.reserveA)/1e6).toLocaleString(void 0,{maximumFractionDigits:0})+' EURC + '+(Number(p.reserveB)/1e6).toLocaleString(void 0,{maximumFractionDigits:0})+' USDC. TVL: '+ubFormatUSD(p.tvl)+'.';}return s;}

