function ubSearchGlobal(){var q=ub$('ub-global-search')?.value?.trim()?.toLowerCase();if(!q)return;var results=[];if(q.includes('send')||q.includes('pay'))results.push({icon:'fa-paper-plane',color:'text-blue-400',title:'Send',desc:'Send USDC or EURC instantly',action:'ubActionSend()'});if(q.includes('bridge'))results.push({icon:'fa-right-left',color:'text-cyan-400',title:'Bridge Tokens',desc:'Cross-chain via CCTP V2',action:"switchTab('bridge')"});if(q.includes('swap'))results.push({icon:'fa-exchange-alt',color:'text-yellow-400',title:'Swap Tokens',desc:'EURC ↔ USDC via AMM',action:"switchTab('dex')"});if(q.includes('deposit')||q.includes('receive'))results.push({icon:'fa-arrow-down',color:'text-green-400',title:'Deposit/Receive',desc:'View your wallet address',action:'ubActionDeposit()'});if(q.includes('invoice')||q.includes('request'))results.push({icon:'fa-file-invoice',color:'text-yellow-400',title:'Create Invoice',desc:'Send request',action:'ubActionInvoice()'});if(q.includes('agent')||q.includes('automate'))results.push({icon:'fa-robot',color:'text-violet-400',title:'AI Agents',desc:'Manage autonomous agents',action:"switchTab('agents')"});if(q.includes('pool')||q.includes('liquidity')||q.includes('lp'))results.push({icon:'fa-water',color:'text-cyan-400',title:'Liquidity Pool',desc:'EURC/USDC AMM',action:"switchTab('dex')"});if(!results.length)results.push({icon:'fa-search',color:'text-gray-400',title:'No results',desc:'Try: send, pay, bridge, swap, deposit, invoice, agent, liquidity',action:''});var el=ub$('ub-search-results');if(!el)return;el.innerHTML=results.map(r=>'<div class="flex items-center gap-3 px-4 py-2.5 border-b border-gray-700/30 hover:bg-gray-800/30 cursor-pointer" onclick="'+(r.action||'')+'"><i class="fas '+r.icon+' '+r.color+' text-sm w-5 text-center"></i><div><div class="text-white text-xs font-semibold">'+r.title+'</div><div class="text-gray-500 text-[10px]">'+r.desc+'</div></div></div>').join('');ub$('ub-global-search').value='';}

function ubRenderNotifications(){var el=ub$('ub-notif-list');if(!el)return;try{var log=JSON.parse(localStorage.getItem('ub_event_log_v1')||'[]');if(!log.length){el.innerHTML='<div class="text-center py-4 text-gray-600 text-xs">No notifications</div>';return;}el.innerHTML=log.slice(0,8).map(l=>{var icon='fa-bell',c='text-gray-400';if(l.name.includes('payment')){icon='fa-paper-plane';c='text-blue-400';}else if(l.name.includes('invoice')){icon='fa-file-invoice';c='text-yellow-400';}else if(l.name.includes('agent')){icon='fa-robot';c='text-violet-400';}else if(l.name.includes('rule')){icon='fa-clock';c='text-purple-400';}return'<div class="flex items-center gap-2 px-4 py-2 border-b border-gray-700/30 text-xs"><i class="fas '+icon+' '+c+' w-4 text-center"></i><span class="text-gray-300 flex-1">'+l.name.replace(/^ub:/,'').replace(/_/g,' ')+'</span><span class="text-gray-600 text-[10px]">'+ubTimeAgo(l.time)+'</span></div>';}).join('');}catch(_){}}

function ubRenderEcosystem(){ubRenderNotifications();}

