e;window.ubExecuteCCTPMove=ubExecuteCCTPMove;window.LiquidityRouter=LiquidityRouter;window.ubSearchGlobal=ubSearchGlobal;window.ubRenderNotifications=ubRenderNotifications;window.ubRenderSDKRef=ubRenderSDKRef;window.SmartRouter=SmartRouter;window.IntentEngine=IntentEngine;
